let phoneLocked=false,lockPin='',phoneIdleTimer=null,lockSubmitting=false;
function lockPhone(){phoneLocked=true;lockPin='';controller?.abort();stopVoice();document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.querySelector('.page').inert=true;document.body.classList.add('phone-is-locked');showLock();clearTimeout(phoneIdleTimer)}
function showLock(){const saved=localRead('lock',null),host=document.querySelector('#lockScreen');host.hidden=false;host.innerHTML=`<div class="lock-phone"><div class="crest">♔</div><div class="eyebrow">ROSE PALAIS</div><div class="lock-time">${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</div><h2>${saved?'欢迎回到小宫殿':'设置你的解锁密码'}</h2>${saved?`<p>请输入 6 位数字密码</p><div class="pin-dots" aria-label="已输入 ${lockPin.length} 位">${Array.from({length:6},(_,i)=>`<i class="${i<lockPin.length?'filled':''}"></i>`).join('')}</div><div id="lockError" role="status"></div><div class="keypad">${['1','2','3','4','5','6','7','8','9','清空','0','⌫'].map(n=>`<button data-digit="${n}" ${lockSubmitting?'disabled':''}>${n}</button>`).join('')}</div><p class="lock-hint">忘记密码无法恢复。清除此网站浏览器数据也会清除本地记录。</p>`:`<form id="setupPin"><label>6 位数字密码<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="new-password" required aria-label="新解锁密码"></label><label>再次输入<input name="confirmPin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="new-password" required aria-label="确认解锁密码"></label><div id="lockError" role="status"></div><button class="primary full">设置并进入</button></form><p class="lock-hint">密码只用于当前浏览器的屏幕锁。它不加密本地记录，也不能替代网站访问权限。请记住密码。</p>`}</div>`;
  if(saved){host.querySelectorAll('[data-digit]').forEach(b=>b.onclick=()=>pinKey(b.dataset.digit));const attempts=localRead('lockAttempts',{count:0,until:0});if(attempts.until>Date.now())$('#lockError').textContent='尝试次数过多，请稍后再试。'}else $('#setupPin').onsubmit=async e=>{e.preventDefault();if(lockSubmitting)return;const f=e.target,pin=f.pin.value;if(pin!==f.confirmPin.value){$('#lockError').textContent='两次密码不一致';return}const b=f.querySelector('button');b.disabled=true;lockSubmitting=true;try{const salt=[...crypto.getRandomValues(new Uint8Array(16))],hash=await PalaisCore.pinDigest(pin,salt);localSave('lock',{salt,hash});unlockPhone()}catch(err){$('#lockError').textContent=err.message}finally{lockSubmitting=false;b.disabled=false}};
}
async function pinKey(value){if(!phoneLocked||lockSubmitting)return;const attempts=localRead('lockAttempts',{count:0,until:0});if(attempts.until>Date.now()){toast('请等待 '+Math.ceil((attempts.until-Date.now())/1000)+' 秒后再试');return}if(value==='清空')lockPin='';else if(value==='⌫')lockPin=lockPin.slice(0,-1);else if(/^\d$/.test(value)&&lockPin.length<6)lockPin+=value;showLock();if(lockPin.length===6){lockSubmitting=true;showLock();try{const saved=localRead('lock',null),hash=await PalaisCore.pinDigest(lockPin,saved.salt);if(hash===saved.hash){localSave('lockAttempts',{count:0,until:0});unlockPhone()}else{const count=(attempts.until&&attempts.until<Date.now()?0:attempts.count)+1;localSave('lockAttempts',{count,until:count>=5?Date.now()+30000:0});lockPin='';lockSubmitting=false;showLock();$('#lockError').textContent=count>=5?'连续输入错误，请等待 30 秒。':'密码不正确，请重试。'}}catch{lockPin='';lockSubmitting=false;showLock();$('#lockError').textContent='解锁失败，请重试'}finally{lockSubmitting=false}}}
function unlockPhone(){phoneLocked=false;lockPin='';$('#lockScreen').hidden=true;document.body.classList.remove('phone-is-locked');document.querySelector('.page').inert=false;resetPhoneIdle();render();memoryTick();calendarTick()}
function resetPhoneIdle(){clearTimeout(phoneIdleTimer);if(!phoneLocked)phoneIdleTimer=setTimeout(lockPhone,5*60000)}
function renderSecurity(){screen.innerHTML=`<section class="view">${title('小宫殿的门锁','YOUR PRIVATE LITTLE SPACE')}<div class="notice">已开启 6 位数字解锁密码。重新打开、切到后台或闲置 5 分钟时锁屏。</div><form id="changePin"><label>当前密码<input name="oldPin" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="current-password"></label><label>新密码<input name="newPin" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="new-password"></label><label>再次输入新密码<input name="confirmPin" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="new-password"></label><button class="primary full">修改解锁密码</button></form><button class="secondary full" id="lockNow">立即锁屏</button><p class="api-note">这是当前浏览器的屏幕锁，本地数据没有加密。网站访问仍由你的私人链接权限控制。密码只保存加盐后的校验值，不能恢复原密码。</p></section>`;$('#lockNow').onclick=lockPhone;$('#changePin').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const saved=localRead('lock',null);if(!saved)throw Error('请先设置解锁密码');if(await PalaisCore.pinDigest(f.oldPin.value,saved.salt)!==saved.hash)throw Error('当前密码不正确');if(f.newPin.value!==f.confirmPin.value)throw Error('两次新密码不一致');const salt=[...crypto.getRandomValues(new Uint8Array(16))],hash=await PalaisCore.pinDigest(f.newPin.value,salt);localSave('lock',{salt,hash});f.reset();toast('解锁密码已更新')}catch(err){toast(err.message)}finally{b.disabled=false}}}
function bootLock(){lockPhone();document.addEventListener('keydown',e=>{if(!phoneLocked){resetPhoneIdle();return}if($('#setupPin'))return;if(/^\d$/.test(e.key)){e.preventDefault();pinKey(e.key)}else if(e.key==='Backspace'){e.preventDefault();pinKey('⌫')}});document.addEventListener('pointerdown',()=>{if(!phoneLocked)resetPhoneIdle()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!phoneLocked)lockPhone()});setInterval(()=>{if(!phoneLocked){memoryTick();calendarTick()}},60000)}
window.addEventListener('DOMContentLoaded',bootLock);
